ar(30) // e.g., \"Sales\", \"Customer Free Program\", \"Lending Of Goods\", \"Fee Service\", \"Warranty\", \"Others\"\n  notes              String?          @db.Text\n  deletedAt          DateTime?        @db.Timestamp()\n\n  // customer address\n  customerAddress String? @db.Text\n  contactPerson   String? @db.VarChar(200)\n  contactPhone    String? @db.VarChar(50)\n  contactEmail    String? @db.VarChar(100)\n\n  // Timestamps\n  createdAt DateTime  @default(now())\n  updatedAt DateTime? @updatedAt\n\n  customerId Int\n  userId     Int\n\n  // Relationships\n  Customer        Customer         @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  User            User             @relation(fields: [userId], references: [id])\n  Invoice         Invoice?\n  SalesOrderItems SalesOrderItem[]\n\n  @@index([number])\n  @@index([customerId])\n  @@index([status])\n  @@index([date])\n  @@index([deletedAt])\n  @@map(\"SalesOrders\")\n}\n\nmodel SalesOrderItem {\n  id           Int    @id @default(autoincrement())\n  salesOrderId Int\n  partNumber   String @db.VarChar(100)\n  description  String @db.Text\n  quantity     Int\n  unitPrice    Float\n  totalPrice   Float\n  sortOrder    Int    @default(0)\n\n  // Relationships\n  SalesOrder SalesOrder @relation(fields: [salesOrderId], references: [id], onDelete: Cascade)\n\n  @@index([salesOrderId])\n  @@map(\"SalesOrderItems\")\n}\n\nenum SalesOrderStatus {\n  Draft\n  Confirmed\n  Sent\n  Pending\n  Processing\n  Completed\n  Cancelled\n}\n\n// This is your Prisma schema file,\n// learn more about it in the docs: https://pris.ly/d/prisma-schema\n\n// Looking for ways to speed up your queries, or scale easily with your serverless or edge functions?\n// Try Prisma Accelerate: https://pris.ly/cli/accelerate-init\n\ngenerator client {\n  provider     = \"prisma-client\"\n  output       = \"../../src/prisma/client\"\n  moduleFormat = \"cjs\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\nmodel Company {\n  